/* ============================================================
   SPLASH — octopus rig, parallax, bubbles, responsive zoom.
   Ported out of the old splash.html iframe (v2.34). Scoped to
   #splash-section so it never leaks into the app shell.
   ============================================================ */
(function () {
  const SPLASH = document.getElementById('splash-section');
  if (!SPLASH) return;
  // Escala responsive: mantiene las proporciones del diseño (spec a 1.0)
  // reduciendo el zoom cuando la ventana es más estrecha que el diseño.
  const DESIGN_W = 1552;   // 1464 de pastilla + márgenes
  const DESIGN_H = 1385;   // alto total del diseño a escala 1.0
  const BASE_ZOOM = 0.78;  // escala máxima (encaja en 1920×1080)
  function fitZoom() {
    const w = window.innerWidth;
    const h = window.innerHeight;
    // encaja a lo ancho Y a lo alto: en pantallas más bajas (p.ej. MacBook 16")
    // reduce la escala y el fondo negro rellena los laterales
    const z = w <= 980 ? 1 : Math.min(BASE_ZOOM, w / DESIGN_W, h / DESIGN_H);
    SPLASH.style.zoom = z;
    // ancla el footer al fondo real del viewport compensando el zoom
    SPLASH.style.minHeight = (window.innerHeight / z) + 'px';
  }
  window.addEventListener('resize', fitZoom);
  fitZoom();

  // ---- Pompitas al hacer click ----
  // 3 cuadraditos (como los del pulpo) que saltan verticalmente y se desvanecen.
  const BUBBLES = [
    { size: 15, color: '#ffffff', opacity: 1,   dx: 4,  rise: 138, dur: 1050, delay: 0 },
    { size: 10, color: '#8a8f93', opacity: .85, dx: 26, rise: 114, dur: 1200, delay: 100 },
    { size: 7,  color: '#55595c', opacity: .8,  dx: 14, rise: 92,  dur: 1350, delay: 190 },
  ];

  // ---- Variante verde del pulpo (tecla G) ----
  const GREEN_SET = {
    'body': { src: 'data:image/png;base64,', imgW: '161px' },
    'tentacle-left': { src: 'data:image/png;base64,' },
    'tentacle-centre': { src: 'data:image/png;base64,' },
    'tentacle-right': { src: 'data:image/png;base64,', boxH: '77px' },
    'tentacle-rightmost': { src: 'data:image/png;base64,' },
  };
  const PURPLE_SET = {};   // se captura del DOM al iniciar
  const SMILE_PATCH = { purple: '#707FEE', green: '#2FDC80' };
  let octoVariant = 'purple';

  Object.keys(GREEN_SET).forEach(part => {
    const layer = document.querySelector(`[data-part="${part}"]`);
    const img = layer.querySelector('img');
    PURPLE_SET[part] = { src: img.src, imgW: img.style.width || '', boxH: layer.style.height };
  });

  function setOctoVariant(v) {
    octoVariant = v;
    const set = v === 'green' ? GREEN_SET : PURPLE_SET;
    Object.entries(set).forEach(([part, cfg]) => {
      const layer = document.querySelector(`[data-part="${part}"]`);
      const img = layer.querySelector('img');
      img.src = cfg.src;
      img.style.width = cfg.imgW || '';
      if (cfg.boxH) layer.style.height = cfg.boxH;
      else if (v === 'purple') layer.style.height = PURPLE_SET[part].boxH;
    });
    // parche de la sonrisa del color del cuerpo
    const patch = document.querySelector('.octo-smile rect');
    if (patch) patch.setAttribute('fill', SMILE_PATCH[v]);
    SPLASH.classList.toggle('octo-green', v === 'green');
  }

  // G = verde · P = morado (verde por defecto)
  document.addEventListener('keydown', (e) => {
    if (e.metaKey || e.ctrlKey) return;
    const k = e.key.toLowerCase();
    if (k === 'g') setOctoVariant('green');
    if (k === 'p') setOctoVariant('purple');
  });

  setOctoVariant('green'); // variante por defecto

  // ---- Sonido de pompita: 3 variantes sintetizadas, en rotación ----
  const POPS = [
    { f0: 320, f1: 900,  attack: .015, decay: .14, gain: .35 },  // clásico
    { f0: 240, f1: 660,  attack: .018, decay: .17, gain: .32 },  // grave y redondo
    { f0: 420, f1: 1150, attack: .012, decay: .11, gain: .3  },  // agudo y chispeante
  ];
  let popIndex = 0;
  let audioCtx = null;

  function playBubbleSound() {
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      audioCtx = audioCtx || new AC();

      const pop = () => {
        const p = POPS[popIndex];
        popIndex = (popIndex + 1) % POPS.length;
        const jitter = 1 + (Math.random() - 0.5) * 0.08;
        const t = audioCtx.currentTime;
        const o = audioCtx.createOscillator();
        const g = audioCtx.createGain();
        o.type = 'sine';
        o.frequency.setValueAtTime(p.f0 * jitter, t);
        o.frequency.exponentialRampToValueAtTime(p.f1 * jitter, t + p.attack + .075);
        g.gain.setValueAtTime(0.0001, t);
        g.gain.exponentialRampToValueAtTime(p.gain, t + p.attack);
        g.gain.exponentialRampToValueAtTime(0.0001, t + p.decay);
        o.connect(g).connect(audioCtx.destination);
        o.start(t);
        o.stop(t + p.decay + .02);
      };

      if (audioCtx.state !== 'running') {
        // desbloqueo Safari/WebKit: buffer mudo arrancado DENTRO del gesto,
        // y resume() sin await para no salir del contexto del click
        const unlock = audioCtx.createBufferSource();
        unlock.buffer = audioCtx.createBuffer(1, 1, 22050);
        unlock.connect(audioCtx.destination);
        unlock.start(0);
        audioCtx.resume().then(pop).catch(() => {});
      } else {
        pop();
      }
    } catch (e) { /* audio no disponible: silencio */ }
  }

  document.addEventListener('click', () => { if (!SPLASH || SPLASH.classList.contains('hidden')) return;
    if (SPLASH.classList.contains('octo-edit')) return;
    if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    playBubbleSound();

    // nacen en la boca del pulpo (cuerpo en 266.5,49.1 + boca en 77.3,78.5)
    const HEAD = { x: 330, y: 122 };
    const jx = (Math.random() - 0.5) * 18;
    const wrap = document.createElement('div');
    wrap.style.cssText = `position:absolute; left:${HEAD.x + jx}px; top:${HEAD.y}px;
      pointer-events:none; z-index:2;`;
    document.getElementById('octo').appendChild(wrap);

    BUBBLES.forEach(b => {
      const s = document.createElement('span');
      const jitter = (Math.random() - 0.5) * 10;
      s.style.cssText = `position:absolute; left:${b.dx + jitter - b.size / 2}px; top:${-b.size / 2}px;
        width:${b.size}px; height:${b.size}px; border-radius:${Math.round(b.size * .28)}px;
        background:${b.color}; opacity:0;`;
      wrap.appendChild(s);
      s.animate([
        { transform: 'translateY(0) scale(.4)',                 opacity: 0 },
        { transform: `translateY(-${b.rise * .25}px) scale(1)`, opacity: b.opacity, offset: .18 },
        { transform: `translateY(-${b.rise}px) scale(.9)`,      opacity: 0 },
      ], { duration: b.dur, delay: b.delay, easing: 'cubic-bezier(.1,.75,.25,1)', fill: 'forwards' });
    });

    setTimeout(() => wrap.remove(), 2400);

    // boca en "O" mientras salen las pompitas: se abre rápido y se cierra con ease-out
    const smile = document.getElementById('octo-smile-path');
    const oMouth = document.getElementById('octo-mouth-o');
    if (smile && oMouth) {
      clearTimeout(window.__octoMouthT);
      window.__octoMouthAnim?.cancel();
      smile.style.display = 'none';
      oMouth.style.display = '';
      window.__octoMouthAnim = oMouth.animate(
        [{ transform: 'scale(.25)' }, { transform: 'scale(1)' }],
        { duration: 130, easing: 'cubic-bezier(.2,.7,.3,1)', fill: 'forwards' });
      window.__octoMouthT = setTimeout(() => {
        const close = oMouth.animate(
          [{ transform: 'scale(1)' }, { transform: 'scale(0)' }],
          { duration: 280, easing: 'cubic-bezier(.16,.8,.3,1)', fill: 'forwards' });
        window.__octoMouthAnim = close;
        close.onfinish = () => {
          oMouth.style.display = 'none';
          smile.style.display = '';
          smile.animate(
            [{ transform: 'scale(.25)' }, { transform: 'scale(1)' }],
            { duration: 220, easing: 'cubic-bezier(.16,.8,.3,1)', fill: 'forwards' });
        };
      }, 620);
    }
  });

  // ---- Pulpito: reacción al ratón ----
  // mousemove solo registra el objetivo; un bucle rAF interpola cada frame
  // (las transiciones CSS a frecuencia de mousemove dan tirones en Safari).
  const pupils = document.querySelectorAll('#octo .pupil');
  const glints = document.querySelectorAll('#octo .glint');
  const octo = document.getElementById('octo');
  const octoBody = document.querySelector('.octo-body');

  const target = { px: 0, py: 0, bx: 0, by: 0, rot: 0 };  // objetivo (pupilas / cuerpo)
  const state  = { px: 0, py: 0, bx: 0, by: 0, rot: 0 };  // posición interpolada

  // WebKit/Safari: con zoom en el body, getBoundingClientRect devuelve px de layout
  // (sin escalar), mientras clientX/Y son px visuales. Detectamos y corregimos.
  function rectScaleFix() {
    const z = parseFloat(SPLASH.style.zoom || 1);
    if (z === 1) return 1;
    const w = SPLASH.getBoundingClientRect().width;
    return (w > window.innerWidth * 1.02) ? z : 1; // Safari → multiplicar rects por z
  }

  document.addEventListener('mousemove', (e) => { if (!SPLASH || SPLASH.classList.contains('hidden')) return;
    const f = rectScaleFix();
    const rect = octo.getBoundingClientRect();
    const cx = (rect.left + rect.width * 0.52) * f;
    const cy = (rect.top + rect.height * 0.38) * f;
    const dx = e.clientX - cx;
    const dy = e.clientY - cy;
    const angle = Math.atan2(dy, dx);
    const dist = Math.hypot(dx, dy);
    const pupilDist = Math.min(5.5, dist / 60);
    const bodyDistX = Math.min(5, dist / 150);
    const bodyDistY = Math.min(11, dist / 95); /* vertical: más recorrido con la distancia */
    target.px = Math.cos(angle) * pupilDist;
    target.py = Math.sin(angle) * pupilDist;
    target.bx = Math.cos(angle) * bodyDistX;
    target.by = Math.sin(angle) * bodyDistY;
    // rotación muy ligera hacia el cursor (máx ±3°)
    target.rot = Math.max(-3, Math.min(3, dx / 160));
  });

  (function animate() {
    // lerp: pupilas ágiles, cuerpo perezoso
    state.px += (target.px - state.px) * 0.22;
    state.py += (target.py - state.py) * 0.22;
    state.bx += (target.bx - state.bx) * 0.08;
    state.by += (target.by - state.by) * 0.08;
    state.rot += (target.rot - state.rot) * 0.06;

    if (!SPLASH.classList.contains('octo-edit')) {
      pupils.forEach(p =>
        p.setAttribute('transform', `translate(${state.px.toFixed(2)} ${state.py.toFixed(2)})`));
      // destello: 25% del recorrido, pero siempre confinado dentro de la pupila
      {
        const GB = { x: -3.6, y: -3.5 };            // offset base destello→centro pupila
        const MAX = 10.5 - 3.4 - 0.4;               // radio pupila − radio destello − margen
        let gx = state.px * 0.25, gy = state.py * 0.25;
        let rx = GB.x + gx - state.px, ry = GB.y + gy - state.py; // posición relativa a la pupila
        const m = Math.hypot(rx, ry);
        if (m > MAX) { rx *= MAX / m; ry *= MAX / m; }
        gx = state.px + rx - GB.x; gy = state.py + ry - GB.y;
        glints.forEach(g =>
          g.setAttribute('transform', `translate(${gx.toFixed(2)} ${gy.toFixed(2)})`));
      }
      octoBody.style.transform =
        `translate3d(${state.bx.toFixed(2)}px, ${state.by.toFixed(2)}px, 0) rotate(${state.rot.toFixed(2)}deg)`;
    }
    requestAnimationFrame(animate);
  })();

  // ---- Editor de colocación del pulpo ----
  // Tecla E: activar/desactivar. Arrastra las piezas con el ratón,
  // o click para seleccionar y flechas para mover 1px (Shift = 10px).
  // "Copiar CSS" copia las posiciones finales.
  (() => {
    const panel = document.createElement('div');
    panel.id = 'octo-editor';
    SPLASH.appendChild(panel);

    const layers = [...document.querySelectorAll('.octo-layer')];
    let selected = null;

    const zoom = () => parseFloat(SPLASH.style.zoom || 1);

    function refresh() {
      panel.innerHTML = '<b>EDITOR PULPO</b> <span class="hint">(E para salir)</span><br>' +
        layers.map(l => {
          const p = l.dataset.part, s = l.style;
          return `<div class="row${l === selected ? ' sel' : ''}">${p}: left:${parseFloat(s.left)}px; top:${parseFloat(s.top)}px;</div>`;
        }).join('') +
        '<div class="hint">arrastra · click+flechas (Shift=10px)</div>' +
        '<button id="octo-copy">Copiar CSS</button> <span id="octo-copied" class="hint"></span>';
      panel.querySelector('#octo-copy').onclick = () => {
        const css = layers.map(l =>
          `[data-part="${l.dataset.part}"] { left: ${parseFloat(l.style.left)}px; top: ${parseFloat(l.style.top)}px; }`
        ).join('\n');
        navigator.clipboard.writeText(css).then(() => {
          panel.querySelector('#octo-copied').textContent = '¡copiado!';
          setTimeout(refresh, 1200);
        });
      };
    }

    document.addEventListener('keydown', (e) => {
      if (e.key.toLowerCase() === 'e' && !e.metaKey && !e.ctrlKey) {
        SPLASH.classList.toggle('octo-edit');
        if (SPLASH.classList.contains('octo-edit')) refresh();
        return;
      }
      if (!SPLASH.classList.contains('octo-edit') || !selected) return;
      const step = e.shiftKey ? 10 : 1;
      const moves = { ArrowLeft: [-step, 0], ArrowRight: [step, 0], ArrowUp: [0, -step], ArrowDown: [0, step] };
      if (moves[e.key]) {
        e.preventDefault();
        selected.style.left = (parseFloat(selected.style.left) + moves[e.key][0]) + 'px';
        selected.style.top  = (parseFloat(selected.style.top)  + moves[e.key][1]) + 'px';
        refresh();
      }
    });

    layers.forEach(l => {
      l.addEventListener('pointerdown', (e) => {
        if (!SPLASH.classList.contains('octo-edit')) return;
        e.preventDefault();
        selected = l;
        const z = zoom();
        const startX = e.clientX, startY = e.clientY;
        const startL = parseFloat(l.style.left), startT = parseFloat(l.style.top);
        const move = (ev) => {
          l.style.left = (startL + (ev.clientX - startX) / z) + 'px';
          l.style.top  = (startT + (ev.clientY - startY) / z) + 'px';
          refresh();
        };
        const up = () => {
          document.removeEventListener('pointermove', move);
          document.removeEventListener('pointerup', up);
          refresh();
        };
        document.addEventListener('pointermove', move);
        document.addEventListener('pointerup', up);
        refresh();
      });
    });
  })();
  window.__splashFitZoom = fitZoom;
})();
